package com.citacloud.springboot.contacloud.app.services;
import net.sf.jasperreports.engine.*; import net.sf.jasperreports.engine.data.JRMapCollectionDataSource; import org.junit.jupiter.api.Test; import java.io.InputStream; import java.math.BigDecimal; import java.nio.file.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class CierreCajaPdfTemplateTest {@Test void plantillaCompilaYRenderiza() throws Exception {try(InputStream in=getClass().getResourceAsStream("/reports/cash-close/cash-close.jrxml")){assertNotNull(in);var report=JasperCompileManager.compileReport(in);Map<String,Object> p=new HashMap<>();p.put("companyName","EMPRESA DEMO");p.put("companyTaxId","101-00000-1");p.put("companyLogo",null);p.put("number","CIE-000001");p.put("shift","TURNO-1-27102026-CAJA01");p.put("cash","Caja principal");p.put("branch","Sucursal Principal");p.put("openedAt","27/10/2026 08:00");p.put("closedAt","27/10/2026 17:00");p.put("openedBy","Administrador");p.put("closedBy","Administrador");p.put("currency","DOP");p.put("opening",new BigDecimal("2000"));p.put("cashIn",new BigDecimal("15400"));p.put("cashOut",new BigDecimal("1250"));p.put("expected",new BigDecimal("16150"));p.put("counted",new BigDecimal("16160"));p.put("difference",new BigDecimal("10"));p.put("result","SOBRANTE DE CAJA");p.put("notes","Diferencia justificada por redondeo en cobro.");p.put("paymentSummary","Efectivo: DOP 15,400.00   |   Tarjeta: DOP 8,250.00   |   Transferencia bancaria: DOP 3,100.00");Collection<Map<String,?>> rows=List.of(Map.of("denomination",new BigDecimal("2000"),"quantity",5,"subtotal",new BigDecimal("10000")),Map.of("denomination",new BigDecimal("1000"),"quantity",5,"subtotal",new BigDecimal("5000")),Map.of("denomination",new BigDecimal("100"),"quantity",10,"subtotal",new BigDecimal("1000")),Map.of("denomination",new BigDecimal("10"),"quantity",16,"subtotal",new BigDecimal("160")));byte[] pdf=JasperExportManager.exportReportToPdf(JasperFillManager.fillReport(report,p,new JRMapCollectionDataSource(rows)));assertTrue(pdf.length>1000);Path out=Path.of("target","pdf-qa","cierre-caja-muestra.pdf");Files.createDirectories(out.getParent());Files.write(out,pdf);}}}
